using Eto.Drawing; using Eto.Forms; using Rhino; using Rhino.UI;
namespace RhinoContextAssist;
internal sealed class ContextToolbarForm:Form{
 readonly Label caption=new();readonly StackLayout primary=new(){Orientation=Orientation.Horizontal,Spacing=4};readonly StackLayout more=new(){Orientation=Orientation.Horizontal,Spacing=4,Visible=false};readonly Action<ContextAction> execute;readonly Action dismiss;
 public ContextToolbarForm(Action<ContextAction> e,Action d){execute=e;dismiss=d;Title="Context Assist";ShowInTaskbar=false;ShowActivated=false;Topmost=true;Resizable=false;WindowStyle=WindowStyle.None;Padding=7;this.UseRhinoStyle();Content=new StackLayout{Spacing=4,Items={caption,primary,more}};}
 Button Make(ContextAction a,bool favorite){var b=new Button{Text=(favorite?"★ ":"")+a.Label,ToolTip=a.Hint,Height=28};b.Click+=(_,_)=>execute(a);return b;}
 public void UpdateActions(SelectionContext c,IReadOnlyList<ContextAction>a,ContextAssistSettings s){caption.Text=c.Caption;primary.Items.Clear();more.Items.Clear();more.Visible=false;var n=Math.Min(s.PrimaryCount,a.Count);foreach(var x in a.Take(n))primary.Items.Add(Make(x,s.IsFavorite(c.Kind,x.Id)));var rest=a.Skip(n).ToList();if(rest.Count>0){var mb=new Button{Text=$"Mehr … ({rest.Count})",Height=28};mb.Click+=(_,_)=>{more.Visible=!more.Visible;Size=new Size(-1,-1);};primary.Items.Add(mb);foreach(var x in rest)more.Items.Add(Make(x,s.IsFavorite(c.Kind,x.Id)));}var close=new Button{Text="×",ToolTip="Ausblenden",Width=30,Height=28};close.Click+=(_,_)=>dismiss();primary.Items.Add(close);}
 public void ShowAt(SelectionContext c,PopupPositionMode mode){PointF p=Mouse.Position;if(mode==PopupPositionMode.Geometry&&c.Anchor.IsValid){var v=RhinoDoc.ActiveDoc?.Views.ActiveView;if(v!=null){var q=v.ActiveViewport.WorldToClient(c.Anchor);var sr=v.ScreenRectangle;p=new PointF((float)(sr.Left+q.X+14),(float)(sr.Top+q.Y+18));}}Location=new Point((int)p.X+14,(int)p.Y+18);Show();var w=Screen.FromPoint(p).WorkingArea;var l=(int)w.Left;var t=(int)w.Top;var r=(int)w.Right;var b=(int)w.Bottom;var x=Math.Clamp(Location.X,l,Math.Max(l,r-Width));var y=Math.Clamp(Location.Y,t,Math.Max(t,b-Height));Location=new Point(x,y);}}
